// Usage from deps/ui: node scripts/gen_pinyin_data.mjs > src/shared/pinyin_data.ml
// Freeze the locked tiny-pinyin/ICU result so native and Web search agree.
import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';

const require = createRequire(import.meta.url);
const pinyin = require('tiny-pinyin');
const { version } = require('tiny-pinyin/package.json');
const license = readFileSync(require.resolve('tiny-pinyin/LICENSE'), 'utf8');
if (!pinyin.isSupported()) throw new Error('tiny-pinyin requires Chinese ICU support');

console.log('(* Generated by scripts/gen_pinyin_data.mjs; do not edit.');
console.log(`   tiny-pinyin ${version}; Node ${process.version}; ICU ${process.versions.icu}. *)`);
console.log(`(* ${license.trim()} *)\n`);
console.log('(* U+3400..U+9FFF; a dot preserves the original unconverted character. *)');
console.log('let initials =');
let initials = '';
for (let cp = 0x3400; cp <= 0x9fff; cp++) {
  const text = pinyin.convertToPinyin(String.fromCodePoint(cp), '', false);
  const initial = text[0].toLowerCase();
  initials += /^[a-z]$/.test(initial) ? initial : '.';
}
const chunks = initials.match(/.{1,128}/g);
chunks.forEach((chunk, index) => {
  console.log(`${index === 0 ? '  "' : '   '}${chunk}${index === chunks.length - 1 ? '"' : '\\'}`);
});
